 "ArrivedAt"="ArrivedAt"+d,"CheckedOutAt"="CheckedOutAt"+d,"FreeRefundDeadline"="FreeRefundDeadline"+d,
 "CreatedAt"=least("CreatedAt"+d,now()-interval '1 day'),"ConfirmedAt"=least("ConfirmedAt"+d,now()-interval '1 hour'),"UpdatedAt"=now()
 WHERE "Id"=m.id AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
 UPDATE casazen_test."Payments" SET "ProcessedAt"=least("ProcessedAt"+d,now()),"CreatedAt"=least("CreatedAt"+d,now()-interval '1 day'),"UpdatedAt"=now() WHERE "BookingId"=m.id AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
 UPDATE casazen_test."InternalActivities" SET "ScheduledAt"="ScheduledAt"+d,"Deadline"="Deadline"+d,"CompletedAt"="CompletedAt"+d WHERE ("BookingId"=m.id OR ("EntityId"=m.id AND "EntityType"='Booking')) AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
 UPDATE casazen_test."AlloggiatiWebReports" SET "ReportedAt"="ReportedAt"+d,"ScheduledFor"="ScheduledFor"+d,"UpdatedAt"=now() WHERE "BookingId"=m.id AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
 UPDATE casazen_test."ManualComplianceProofs" SET "Day"=m.new_in,"UploadedAt"=least("UploadedAt"+d,now()) WHERE "PropertyId"=m.property_id AND "Kind"=1 AND "Day"=m.old_in AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
 UPDATE casazen_test."SwissComplianceReceipts" SET "ReportDate"="ReportDate"+d,"UploadedAt"=least("UploadedAt"+d,now()) WHERE "PropertyId"=m.property_id AND "Type"='Police' AND "ReportDate"::date=m.old_in AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
 UPDATE casazen_test."ComplianceSendLogEntries" SET "SentAt"=least("SentAt"+d,now()) WHERE "BookingId"=m.id AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
 UPDATE casazen_test."FiscalDocuments" SET "ServicePeriodFrom"=m.new_in,"ServicePeriodTo"=m.new_out,"UpdatedAt"=now() WHERE "BookingId"=m.id AND "Purpose"=1 AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
 UPDATE casazen_test."FiscalDocumentLines" l SET "Description"=replace(replace(l."Description",m.old_out::text,m.new_out::text),m.old_in::text,m.new_in::text)
 FROM casazen_test."FiscalDocuments" f WHERE f."Id"=l."DocumentId" AND f."BookingId"=m.id AND f."Purpose"=1 AND f."OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
 UPDATE casazen_test."StayTouristTaxes" SET "CalculationHash"=encode(sha256(convert_to('stay-tourist-tax:v2|'||m.new_in::text||'|'||m.new_out::text||'|status:0|rate:f22cb6ed164e1574b5dc24d26e3a47ef|guest:0|guest:1|total:'||to_char("Total",'FM999999990.00')||'|amount:0:'||to_char("Total"/2,'FM999999990.00')||'|amount:1:'||to_char("Total"/2,'FM999999990.00')||'|collector:Host|rule:-','UTF8')),'hex'),"CollectedAt"=least("CollectedAt"+d,now()),"UpdatedAt"=now()
 WHERE "BookingId"=m.id AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8';
 UPDATE casazen_test."OwnerLedgerEntries" e SET "ServiceDate"="ServiceDate"+m.days,
 "RecognitionDate"=CASE WHEN "RecognitionDate"=m.old_out THEN m.new_out ELSE "RecognitionDate" END,
 "PaymentDate"=least("PaymentDate"+m.days,current_date),
 "FxDate"=CASE WHEN "FxDate"=m.old_out THEN m.new_out WHEN "FxDate"=m.old_in THEN m.new_in ELSE "FxDate" END
 WHERE e."OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND (e."SourceId"=m.id OR e."SourceReference"=replace(m.id::text,'-','') OR e."SourceId" IN (SELECT "Id" FROM casazen_test."Payments" WHERE "BookingId"=m.id AND "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8'));
 END LOOP;
 IF EXISTS(SELECT 1 FROM casazen_test."Bookings" a JOIN casazen_test."Bookings" b ON a."PropertyId"=b."PropertyId" AND a."Id"<b."Id" AND a."CheckInDate"<b."CheckOutDate" AND b."CheckInDate"<a."CheckOutDate" WHERE a."OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8') THEN RAISE EXCEPTION 'Overlapping demo stays'; END IF;
 UPDATE casazen_test."OwnerClosePeriods" SET "IsDirty"=true,"DirtySince"=now(),"UpdatedAt"=now() WHERE "OrgId"='ad979b3b-e739-49d6-84a4-c2c1e4f8f1e8' AND "PeriodYear"=2026 AND "PeriodMonth" IN (10,11,12);
END $demo$;
